using System;using System.IO;using System.Reflection;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
[InitializeOnLoad]public static class SkillSpritePlayChecks {
 const string Pending="SkillSpritePlay";static List<string> rows;static TrainingFighter f;static ArmoredStaticPoseView view;static TrainingMove move;static TrainingApprovedCharacter character;static int count,stage;static long start;static string report,sourceBytes;static double deadline;static float duration;static FieldInfo timer=typeof(TrainingFighter).GetField("timer",BindingFlags.NonPublic|BindingFlags.Instance);static TrainingMoveSpatialProfile spatial;
 static SkillSpritePlayChecks(){if(SessionState.GetBool(Pending,false))EditorApplication.update+=Tick;}
 public static void Run(){EditorSceneManager.OpenScene(TrainingFlowSession.TrainingScene);SessionState.SetBool(Pending,true);EditorApplication.update-=Tick;EditorApplication.update+=Tick;EditorApplication.EnterPlaymode();}
 static void C(bool ok,string text){if(!ok)throw new Exception(text);rows.Add("PASS "+text);count++;}
 static void Frame(float frame){timer.SetValue(f,frame/60f);view.Present(f,"Attack",0);}
 static TrainingSpriteSequence Seq(int hold=2)=>new TrainingSpriteSequence{frames=new[]{new TrainingSpriteFrame{sprite=character.IdleSprite,holdFrames=hold},new TrainingSpriteFrame{sprite=character.ForwardSprite,holdFrames=3},new TrainingSpriteFrame{sprite=character.crouchAction.poses[0].sprite,holdFrames=1}}};
 static void Setup(){rows=new List<string>();var args=Environment.GetCommandLineArgs();int i=Array.IndexOf(args,"-spritePlayReport");report=i<0?"Temp/sprite-play.txt":args[i+1];deadline=EditorApplication.timeSinceStartup+90;var hud=UnityEngine.Object.FindAnyObjectByType<TrainingOverlay>();hud.Session.enabled=false;f=hud.player;f.TrainingSession=f.opponent.TrainingSession=null;view=f.GetComponent<ArmoredStaticPoseView>();character=view.characterProfile;move=f.moveSet.Find(TrainingCommand.Light);duration=move.Duration;var source=AssetDatabase.LoadAssetAtPath<TrainingMoveData>("Assets/Shioka/調整Data/Fighter/Awari/Skill/5LP/Data.asset");sourceBytes=File.ReadAllText(AssetDatabase.GetAssetPath(source));C(move.spriteSequence==null||move.spriteSequence.frames.Length==0,"adopted weakP remains unconfigured legacy sequence");C(!ReferenceEquals(move,source.data),"runtime move is detached from source");f.InputBuffer.Push(TrainingCommand.Light,f.LockKind);stage=0;}
 static void Tick(){try{if(!EditorApplication.isPlaying||Time.frameCount<5)return;if(rows==null){Setup();return;}if(EditorApplication.timeSinceStartup>deadline)throw new Exception("Sprite Play timeout stage "+stage);if(stage==0&&f.CurrentPhase==TrainingFighter.Phase.Attack){Time.timeScale=0;Frame(8);C(view.image.sprite==character.weakPunch,"empty sequence preserves active weak single pose");Frame(2);C(view.image.sprite==character.IdleSprite,"empty sequence preserves startup fallback");move.spriteSequence=Seq();Frame(0);C(view.image.sprite==character.IdleSprite,"sequence starts at action frame0");Frame(2);C(view.image.sprite==character.ForwardSprite,"runtime exact integer hold boundary");C(!f.HitboxActive,"sprite boundary does not enable startup HitBox");spatial=ScriptableObject.CreateInstance<TrainingMoveSpatialProfile>();spatial.keys=new[]{new TrainingSpatialKey{visualOffset=new Vector3(0,.12f,.2f),hitCenter=move.center,hitHalfSize=move.halfSize,hurt=new TrainingSpatialHurt[0]}};move.spatialProfile=spatial;Frame(2);C(Vector3.Distance(view.image.transform.localPosition,new Vector3(.2f*f.Facing,.12f,0))<.0001f,"sequence preserves existing spatial image offset");f.opponent.GetComponent<TrainingMotor2D>().Teleport(new Vector2(f.transform.position.x-2,.01f));f.RefreshTrainingFacing();Frame(2);C(view.image.flipX&&Mathf.Abs(view.image.transform.localPosition.x+.2f)<.0001f,"sequence mirrors with facing and spatial offset");Frame(7.2f);C(view.image.sprite==character.crouchAction.poses[0].sprite,"fractional move phase uses unchanged display clock");Frame(20);C(view.image.sprite==character.crouchAction.poses[0].sprite,"short sequence holds through recovery");move.spriteSequence=Seq(200);Frame(20);C(view.image.sprite==character.IdleSprite,"long sequence is not rescaled into move duration");move.spriteSequence.frames[0].holdFrames=0;Frame(8);C(view.image.sprite==character.weakPunch,"malformed runtime sequence safely falls back");move.spriteSequence=Seq(200);Frame(0);C(move.Duration==duration&&move.startupFrames==7.2f&&move.activeFrames==4.8f&&move.recoveryFrames==13.2f,"presentation edits leave exact move timing unchanged");start=f.InputBuffer.Frame;Time.timeScale=1;stage=1;}else if(stage==1&&f.InputBuffer.Frame-start>36){C(f.CurrentPhase!=TrainingFighter.Phase.Attack,"long sequence does not extend action");C(f.SkillSequenceSprite==null,"sequence ends on action exit");view.Present(f,"Idle",0);C(view.image.sprite==character.IdleSprite,"action exit restores locomotion presentation");C(File.ReadAllText("Assets/Shioka/調整Data/Fighter/Awari/Skill/5LP/Data.asset")==sourceBytes,"Play never saves weakP source");C(f.GetComponent<ApprovedLocomotionTuning>().canonicalProfile==f.opponent.GetComponent<ApprovedLocomotionTuning>().canonicalProfile,"shared locomotion reference preserved");Finish(0);}}
 catch(Exception e){rows?.Add("FAIL "+e);Debug.LogException(e);Finish(1);}}
 static void Finish(int exit){SessionState.SetBool(Pending,false);EditorApplication.update-=Tick;Time.timeScale=1;if(spatial!=null)UnityEngine.Object.DestroyImmediate(spatial);rows?.Add(count+" PASS; exit="+exit+"; logical attack + controlled presentation-clock samples, not physical mouse/key input");if(rows!=null)File.WriteAllLines(report,rows);EditorApplication.Exit(exit);}
}
